import asyncio
import time
import aiohttp
from typing import Any, Optional, Dict, Tuple

_cache: Dict[str, Tuple[Any, float]] = {}

async def fetch_with_retry(
    url: str,
    retries: int = 3,
    cache_time: int = 60,
) -> Dict[str, Any]:
    # Cache kontrolu
    if url in _cache:
        data, timestamp = _cache[url]
        if time.time() - timestamp < cache_time:
            return {"data": data, "error": None, "from_cache": True}
        else:
            del _cache[url]  # Suresi dolmus, temizle

    last_error = None
    for attempt in range(retries + 1):
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    # 4xx hatalarinda retry yapma
                    if 400 <= response.status < 500:
                        return {
                            "data": None,
                            "error": f"Client error: {response.status}",
                            "from_cache": False,
                        }

                    # 5xx hatalarinda retry yap
                    if response.status >= 500:
                        raise Exception(f"Server error: {response.status}")

                    data = await response.json()
                    _cache[url] = (data, time.time())
                    return {"data": data, "error": None, "from_cache": False}

        except Exception as e:
            last_error = str(e)
            if attempt < retries:
                # Exponential backoff
                await asyncio.sleep(2 ** attempt)

    return {"data": None, "error": last_error, "from_cache": False}


def invalidate_cache(url: str) -> None:
    if url in _cache:
        del _cache[url]


def clear_all_cache() -> None:
    _cache.clear()

