const cache = new Map();

function useFetch(url, options = {}) {
  const { retries = 3, cacheTime = 60000 } = options;
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const fetchData = useCallback(async (signal) => {
    // Cache kontrolu
    const cached = cache.get(url);
    if (cached && Date.now() - cached.timestamp < cacheTime) {
      setData(cached.data);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    let lastError = null;
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        const response = await fetch(url, { signal });

        // 4xx hatalarinda retry yapma
        if (response.status >= 400 && response.status < 500) {
          throw new Error(`Client error: ${response.status}`);
        }

        // 5xx hatalarinda retry yap
        if (response.status >= 500) {
          throw new Error(`Server error: ${response.status}`);
        }

        const json = await response.json();
        cache.set(url, { data: json, timestamp: Date.now() });
        setData(json);
        setError(null);
        setLoading(false);
        return;
      } catch (err) {
        if (err.name === 'AbortError') return;

        // 4xx icin retry yapma
        if (err.message.startsWith('Client error')) {
          setError(err);
          setLoading(false);
          return;
        }

        lastError = err;
        if (attempt < retries) {
          await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1000));
        }
      }
    }

    setError(lastError);
    setLoading(false);
  }, [url, retries, cacheTime]);

  useEffect(() => {
    const controller = new AbortController();
    fetchData(controller.signal);
    return () => controller.abort();
  }, [fetchData]);

  const invalidate = useCallback(() => {
    cache.delete(url);
    setData(null);
    setLoading(true);
    const controller = new AbortController();
    fetchData(controller.signal);
  }, [url, fetchData]);

  return { data, error, loading, invalidate };
}
